if(typeof uiMap!=='undefined')uiMap.set('SHAMS Premium',premiumWords.title);
function pw(k,v={}){let s=premiumWords[k]?.[['az','tr','ru','en','ar'].indexOf(lang())]||premiumWords[k]?.[0]||k;for(const [a,b]of Object.entries(v))s=s.replaceAll('{'+a+'}',b);return s}
let premiumState={loaded:false,loading:false,config:null,fund:null,service:null,detail:null,premium:false,csrf:null,recovery:null,error:false};
function premiumMoney(n,currency='USD'){return new Intl.NumberFormat(lang(),{style:'currency',currency}).format(n)}
function premiumPrice(){const d=premiumState.detail;return d?{monthly:premiumMoney(Number(d.price.value)/12,d.price.currency),annual:premiumMoney(Number(d.price.value),d.price.currency),actual:true}:{monthly:'$0.30',annual:'$3.60',actual:false}}
function premiumFundHTML(){const f=premiumState.fund;if(!f)return `<p class="notice" role="status">${pw('fundOffline')}</p><button class="secondarybtn" onclick="loadPremium(true)">${pw('retry')}</button>`;const dollars=n=>premiumMoney(n/1000000),pct=Math.max(0,Math.min(100,f.balance/f.goal*100));return `<div class="fund-stats"><div><small>${pw('balance')}</small><strong>${dollars(f.balance)}</strong></div><div><small>${pw('collected')}</small><b>${dollars(f.collected)}</b></div><div><small>${pw('distributed')}</small><b>${dollars(f.distributed)}</b></div></div><div class="fund-target"><span>${dollars(f.balance)} / ${dollars(f.goal)}</span><b>${pct.toFixed(1)}%</b></div><progress class="fund-progress" max="${f.goal}" value="${Math.max(0,f.balance)}" aria-label="${pw('fund')}"></progress><h3>${pw('history')}</h3>${f.distributions.length?f.distributions.map(d=>`<article class="distribution-row"><div><strong>${esc(d.organization)}</strong><small>${esc(d.date)}</small></div><b>${dollars(d.amount)}</b>${/^\/api\/fund\/documents\/[\w-]{36}$/.test(d.document)?`<a href="${esc(d.document)}" target="_blank" rel="noopener">${pw('proof')} ↗</a>`:''}</article>`).join(''):`<p class="muted">${pw('empty')}</p>`}`}
function premiumPageHTML(){const p=premiumPrice(),s=premiumState,ready=!!(s.service&&s.detail&&s.config?.enabled&&s.csrf&&!s.loading);return `<div data-localized="true" class="premium-page">${head(pw('title'),'')}<section class="card premium-offer"><span class="premium-orbit" aria-hidden="true">✦</span><h2>${pw('monthly',{price:p.monthly})}</h2><p class="premium-annual">${pw('annual',{price:p.annual})}</p>${p.actual?'':`<small class="muted">${pw('reference')}</small>`}<ul class="premium-benefits">${pw('benefits').split('|').map(x=>`<li>✓ ${x}</li>`).join('')}</ul><p role="status" class="premium-status">${s.loading?pw('busy'):s.premium?pw('active'):pw('inactive')}</p><button class="goldbtn wide" onclick="purchasePremium()" ${!ready||s.premium?'disabled':''}>${pw('get')}</button><div class="premium-links"><button class="secondarybtn" onclick="restorePremium()" ${!ready?'disabled':''}>${pw('restore')}</button><button class="textbtn" onclick="loadPremium(true)">${pw('retry')} ↻</button></div>${s.config?.enabled&&s.service?'':`<p class="notice">${pw('unavailable')}</p>`}${s.error?`<p class="error" role="alert">${pw('error')}</p>`:''}${s.config?.product&&s.config?.package?`<a class="source-link" href="https://play.google.com/store/account/subscriptions?sku=${encodeURIComponent(s.config.product)}&package=${encodeURIComponent(s.config.package)}" target="_blank" rel="noopener">${pw('manage')} ↗</a><p class="notice">${pw('cancelNote')}</p>`:''}</section><section class="card premium-fund"><h2>✧ ${pw('fund')}</h2><p class="muted">${pw('only')}</p><div id="premiumFund">${premiumFundHTML()}</div><p class="notice fund-formula">${pw('note')}</p></section>${s.csrf?`<details class="card premium-recovery"><summary>${pw('profile')}</summary>${s.recovery?`<p>${pw('recovery')}</p><code class="recovery-code">${esc(s.recovery)}</code>`:''}<button class="secondarybtn" onclick="newPremiumRecoveryCode()">${pw('newCode')}</button><form onsubmit="event.preventDefault();recoverPremiumProfile(this)"><label>${pw('profile')}<input name="code" autocomplete="off" minlength="43" maxlength="43" required aria-label="${pw('profile')}"></label><button class="secondarybtn" type="submit">${pw('recover')}</button></form></details>`:''}</div>`}
proPage=function(){if(!premiumState.loaded&&!premiumState.loading)setTimeout(()=>loadPremium(),0);return premiumPageHTML()};
function premiumPaint(){const panel=document.querySelector('#app[data-route=pro]');if(panel){panel.innerHTML=premiumPageHTML();if(typeof localizeUI==='function')localizeUI()}document.querySelectorAll('[data-premium-price]').forEach(e=>e.textContent=premiumState.detail?premiumPrice().annual:'Premium');document.querySelectorAll('[data-ad-slot]').forEach(e=>{e.hidden=premiumState.premium});document.documentElement.classList.toggle('has-premium',premiumState.premium)}
async function premiumAPI(path,body){const r=await fetch(path,{method:body===undefined?'GET':'POST',credentials:'same-origin',cache:'no-store',headers:{'Content-Type':'application/json',...(premiumState.csrf?{'X-CSRF-Token':premiumState.csrf}:{})},...(body!==undefined?{body:JSON.stringify(body)}:{})});if(!r.ok)throw Error('premium-api');return r.json()}
async function loadPremium(force=false){if(premiumState.loading)return;if(premiumState.loaded&&!force)return;premiumState.loading=true;premiumPaint();const s=premiumState;s.error=false;s.premium=false;try{const [config,fund,session]=await Promise.all([premiumAPI('/api/premium/config'),premiumAPI('/api/fund'),premiumAPI('/api/session',{})]);s.config=config;s.fund=fund;s.csrf=session.csrf;if(session.recoveryCode)s.recovery=session.recoveryCode;s.service=null;s.detail=null;if(config.enabled){if(window.getDigitalGoodsService&&window.PaymentRequest){try{s.service=await window.getDigitalGoodsService('https://play.google.com/billing');const details=await s.service.getDetails([config.product]);const d=details.find(d=>d.itemId===config.product);if(d?.subscriptionPeriod==='P1Y'&&/^[A-Z]{3}$/.test(d.price?.currency)&&Number(d.price.value)>0)s.detail=d}catch{s.service=null}}const status=await premiumAPI('/api/premium/status');s.premium=status.premium===true}}catch{s.error=true;s.fund=null;s.service=null;s.detail=null;s.premium=false}finally{s.loaded=true;s.loading=false;premiumPaint()}}
async function purchasePremium(){const s=premiumState;if(!s.service||!s.detail||!s.csrf||s.loading||s.premium)return;let response;s.loading=true;premiumPaint();try{const req=new window.PaymentRequest([{supportedMethods:'https://play.google.com/billing',data:{sku:s.config.product}}],{total:{label:pw('title'),amount:{currency:s.detail.price.currency,value:s.detail.price.value}}});response=await req.show();const verified=await premiumAPI('/api/premium/verify',{purchaseToken:response.details.purchaseToken});s.premium=verified.premium===true;await response.complete(s.premium?'success':'unknown');toast(s.premium?pw('active'):pw('pending'))}catch(e){s.premium=false;if(response)try{await response.complete('fail')}catch{}if(e.name!=='AbortError')toast(pw('error'))}finally{s.loading=false;premiumPaint()}}
async function restorePremium(){const s=premiumState;if(!s.service||!s.csrf||s.loading)return;s.loading=true;premiumPaint();try{const purchases=await s.service.listPurchases();let found=false;for(const p of purchases)if(p.itemId===s.config.product){found=true;await premiumAPI('/api/premium/verify',{purchaseToken:p.purchaseToken})}const status=await premiumAPI('/api/premium/status');s.premium=status.premium===true;toast(s.premium?pw('active'):found?pw('pending'):pw('none'))}catch{s.premium=false;toast(pw('error'))}finally{s.loading=false;premiumPaint()}}
async function recoverPremiumProfile(form){try{const s=await premiumAPI('/api/session/recover',{code:form.elements.code.value.trim()});premiumState.csrf=s.csrf;premiumState.recovery=null;await loadPremium(true)}catch{toast(pw('error'))}}
setInterval(async()=>{if(route!=='pro'||!premiumState.loaded||premiumState.loading)return;try{premiumState.fund=await premiumAPI('/api/fund')}catch{premiumState.fund=null}const el=document.querySelector('#premiumFund');if(el)el.innerHTML=premiumFundHTML()},30000);
if(typeof window.addEventListener==='function'){window.addEventListener('focus',()=>{if(premiumState.loaded)loadPremium(true)});window.addEventListener('pageshow',()=>{if(premiumState.loaded)loadPremium(true)})}

async function newPremiumRecoveryCode(){try{const r=await premiumAPI('/api/session/recovery-code',{});premiumState.recovery=r.recoveryCode;premiumPaint();const panel=document.querySelector('.premium-recovery');if(panel)panel.open=true}catch{toast(pw('error'))}}
setTimeout(()=>loadPremium(),0);

